import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, spring, Easing } from "remotion";
import { COLORS, FONTS, headlineGradient } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const CLAMP = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const TituloQuatroFaixas: React.FC<PrimitiveProps> = ({ anim, fps, dark, format, frame }) => {
  const f = useCurrentFrame();
  const params = (anim.params ?? {}) as Record<string, unknown>;
  // `src` is the pipeline's slot; src2..src4 (or a srcs array) carry the rest.
  const src = String(anim.params?.src ?? "");
  const list = Array.isArray(params.srcs) ? (params.srcs as unknown[]) : [];
  const srcs = [0, 1, 2, 3].map((i) => String((i === 0 ? src : params[`src${i + 1}`]) || list[i] || ""));
  const text = String(anim.text ?? "").trim();

  const len = Math.max(1, Math.round((anim.end - anim.start) * fps));
  const landscape = format === "landscape";
  const short = Math.min(frame.width, frame.height);
  const pad = Math.round(short * 0.067);
  const padTop = format === "portrait" ? Math.round(frame.height * 0.13) : pad;
  const padBottom = format === "portrait" ? Math.round(frame.height * 0.15) : pad;
  const gap = Math.round(short * (format === "half" ? 0.014 : 0.02));

  const base = short * (format === "portrait" ? 0.1 : format === "half" ? 0.075 : 0.085);
  const fontSize = Math.round(base * Math.min(1, Math.sqrt(18 / Math.max(18, text.length))));

  const title = spring({ frame: f, fps, config: { damping: 16, stiffness: 140 } });
  const stripsFrom = text ? Math.round(fps * 0.45) : 0;
  const stagger = Math.max(3, Math.min(Math.round(fps * 0.4), Math.round((len * 0.55 - stripsFrom) / 4)));

  const exitStart = Math.max(0, len - Math.round(fps * 0.35));
  const out = interpolate(f, [exitStart, Math.max(exitStart + 1, len)], [1, 0], CLAMP);

  return (
    <AbsoluteFill
      style={{
        fontFamily: FONTS.display,
        opacity: out,
        padding: `${padTop}px ${pad}px ${padBottom}px`,
        flexDirection: landscape ? "row" : "column",
        alignItems: "stretch",
        gap: Math.round(short * 0.04),
      }}
    >
      {text ? (
        <div
          style={{
            flex: landscape ? "0 0 38%" : "0 0 auto",
            display: "flex",
            alignItems: "center",
            justifyContent: landscape ? "flex-start" : "center",
          }}
        >
          <div
            style={{
              fontSize,
              fontWeight: FONTS.displayWeight,
              fontStyle: "italic",
              textTransform: "uppercase",
              lineHeight: 0.98,
              textAlign: landscape ? "left" : "center",
              overflowWrap: "break-word",
              color: dark ? COLORS.textOnDark : COLORS.textOnLight,
              backgroundImage: headlineGradient(),
              WebkitBackgroundClip: "text",
              backgroundClip: "text",
              WebkitTextFillColor: "transparent",
              opacity: interpolate(title, [0, 1], [0, 1], CLAMP),
              transform: `translateY(${interpolate(title, [0, 1], [fontSize * 0.6, 0])}px)`,
            }}
          >
            {text}
          </div>
        </div>
      ) : null}
      <div style={{ flex: 1, minHeight: 0, minWidth: 0, display: "flex", flexDirection: "column", gap }}>
        {srcs.map((s, i) => {
          const start = stripsFrom + i * stagger;
          const p = interpolate(f, [start, start + Math.round(fps * 0.5)], [0, 1], {
            ...CLAMP,
            easing: Easing.bezier(0.16, 1, 0.3, 1),
          });
          const fromLeft = i % 2 === 0;
          const hidden = (1 - p) * 100;
          return (
            <div
              key={i}
              style={{
                flex: 1,
                minHeight: 0,
                position: "relative",
                overflow: "hidden",
                backgroundColor: COLORS.vellum,
                clipPath: fromLeft ? `inset(0 ${hidden}% 0 0)` : `inset(0 0 0 ${hidden}%)`,
              }}
            >
              {s ? (
                <Img
                  src={s}
                  style={{
                    width: "100%",
                    height: "100%",
                    objectFit: "cover",
                    transform: `scale(${interpolate(f, [start, Math.max(start + 1, len)], [1.15, 1], CLAMP)}) translateX(${(fromLeft ? -1 : 1) * (1 - p) * 6}%)`,
                  }}
                />
              ) : (
                <div
                  style={{
                    position: "absolute",
                    left: "-10%",
                    right: "-10%",
                    top: "38%",
                    height: "24%",
                    backgroundColor: `${COLORS.teal}33`,
                    transform: "rotate(-11deg)",
                  }}
                />
              )}
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default TituloQuatroFaixas;
